// ============ EDIT ME ============
const NEWSLETTER_NAME = 'My Weekly Digest';
const MODEL = 'gpt-4o-mini';
// ==================================
const issue = $input.first().json;
const title = issue.title ?? 'New issue';
const link = issue.link ?? '';
const summary = (issue.contentSnippet ?? issue.content ?? '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 800);

const system = `You write short social announcements for the newsletter "${NEWSLETTER_NAME}". Platform-native voice, no hashtag spam, at most one emoji each. Never invent details not present in the issue summary.`;

const user = `A new issue is out.\nTitle: ${title}\nLink: ${link}\nSummary: ${summary}\n\nWrite announcements and return STRICT JSON ONLY (no code fences) with exactly these keys:\n{\n  "bluesky": "max 280 characters INCLUDING the link ${link}",\n  "telegram": "2-3 short lines, include the link",\n  "discord": "2-3 short lines, include the link",\n  "x_draft": "max 260 characters including the link",\n  "linkedin_draft": "3-4 sentences, professional but human, include the link"\n}`;

return [{
  json: {
    title,
    link,
    body: {
      model: MODEL,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      temperature: 0.5,
      response_format: { type: 'json_object' },
    },
  },
}];

let raw = $input.first().json.choices?.[0]?.message?.content ?? '';
raw = raw.replace(/^```(json)?/m, '').replace(/```\s*$/m, '').trim();
let copy;
try {
  copy = JSON.parse(raw);
} catch (e) {
  throw new Error('AI did not return valid JSON. Raw output: ' + raw.slice(0, 300));
}
for (const key of ['bluesky', 'telegram', 'discord', 'x_draft', 'linkedin_draft']) {
  if (typeof copy[key] !== 'string' || !copy[key].trim()) {
    throw new Error(`AI output missing "${key}"`);
  }
}
// Bluesky hard limit is 300 graphemes; stay safely under it.
copy.bluesky = copy.bluesky.slice(0, 295);
return [{ json: copy }];

